using System.Diagnostics;
using System.Numerics;
using System.Reflection;
using System.Runtime.InteropServices;
using UltimateArena.Core;
using UltimateArena.Graphics;
using UltimateArena.Native;
using UltimateArena.Network;
namespace UltimateArena.Tests;
internal static class SelfTests {
    private static void Check(bool condition,string message="Assertion failed"){if(!condition)throw new InvalidOperationException(message);}
    private static void Steps(World w,int count){for(int i=0;i<count;i++)w.Step();}
    public static int Run(){int passed=0,failed=0;void Test(string name,Action body){try{body();Console.WriteLine("PASS "+name);passed++;}catch(Exception e){Console.WriteLine("FAIL "+name+": "+e.Message);failed++;}}
        Test("six original C# weapon definitions",()=>{Check(Weapons.All.Length==6);Check(Weapons.All.Select(w=>w.Name).Distinct().Count()==6);Check(Weapons.All[1].Delay<.07f);});
        Test("wall collision and fixed-step movement",()=>{var p=new Fighter{Position=new(20,0,4),Yaw=MathF.PI/2};for(int i=0;i<180;i++)Movement.Step(p,new(){Forward=1},World.Tick);Check(p.Position.X<23.2f&&p.Position.X>22);});
        Test("jump arc and floor landing",()=>{var p=new Fighter{Position=new(12,0,4)};Movement.Step(p,new(){Jump=true},World.Tick);for(int i=0;i<15;i++)Movement.Step(p,default,World.Tick);Check(p.Position.Y>1);for(int i=0;i<90;i++)Movement.Step(p,default,World.Tick);Check(p.Position.Y==0&&p.Grounded);});
        Test("dodge impulse and cooldown",()=>{var p=new Fighter{Position=new(12,0,4)};Movement.Step(p,new(){Side=1,Dodge=true},World.Tick);Check(p.Velocity.X>14&&p.DodgeCooldown>.8f&&!p.Grounded);});
        Test("stairs traverse into upper gallery",()=>{var p=new Fighter{Position=new(15,0,5),Yaw=MathF.PI};for(int i=0;i<120;i++)Movement.Step(p,new(){Forward=1},World.Tick);Check(p.Position.Y>=2.99f&&p.Position.Z>14,$"position {p.Position}");});
        Test("jump pad launches fighter",()=>{var p=new Fighter{Position=new(0,0,11)};Movement.Step(p,default,World.Tick);Check(p.Velocity.Y>=12);});
        Test("navigation avoids reactor and reaches balcony",()=>{var route=Navigation.Find(new(0,0,8),new(0,0,-8));Check(route.Count>16&&route.Any(p=>MathF.Abs(p.X)>3));Check(Navigation.Find(new(15,0,4),new(15,3,18)).Any(p=>p.Y==3));});
        Test("precision damage score and respawn",()=>{var w=new World(1,0);var a=w.Add("A");var b=w.Add("B");a.Position=new(12,0,5);a.Yaw=0;a.Pitch=0;a.Weapon=3;a.Cooldown=0;a.Invulnerable=0;b.Position=new(12,0,-5);b.Invulnerable=0;b.Armor=0;w.Fire(a);a.Cooldown=0;w.Fire(a);Check(b.Health==0&&a.Score==1);Steps(w,130);Check(b.Health==100&&b.Deaths==1);});
        Test("solid geometry blocks hitscan",()=>{var w=new World(1,0);var a=w.Add("A");var b=w.Add("B");a.Position=new(0,0,8);a.Yaw=0;a.Weapon=3;a.Cooldown=0;b.Position=new(0,0,-8);b.Invulnerable=0;b.Armor=0;w.Fire(a);Check(b.Health==100);});
        Test("rocket detonation does radial damage",()=>{var w=new World(2,0);var a=w.Add("A");var b=w.Add("B");a.Position=new(12,0,5);a.Yaw=0;a.Pitch=-.05f;a.Weapon=4;a.Cooldown=0;b.Position=new(12,0,-5);b.Invulnerable=0;b.Armor=0;w.Fire(a);Steps(w,60);Check(w.Events.Any(e=>e.Kind==EventKind.Explosion));Check(b.Health<100);});
        Test("alternate fire ammo pellets homing and sticky modes",()=>{var w=new World(2,0);var a=w.Add("A");a.Cooldown=0;a.Weapon=2;w.Fire(a,true);Check(a.Ammo[2]==34&&w.Events.Count(e=>e.Kind==EventKind.Trace)==16);a.Cooldown=0;a.Weapon=5;w.Fire(a,true);Check(w.Projectiles[0].Sticky);a.Cooldown=0;a.Weapon=4;w.Fire(a,true);Check(w.Projectiles[1].Homing);a.Cooldown=0;a.Weapon=0;a.Ammo[0]=0;w.Fire(a);Check(a.Ammo[0]==0);});
        Test("armor absorbs sixty percent until depleted",()=>{var w=new World(1,0);var a=w.Add("A");var b=w.Add("B");b.Invulnerable=0;b.Armor=35;w.Damage(b,50,a);Check(MathF.Abs(b.Health-80)<.001f&&MathF.Abs(b.Armor-5)<.001f);});
        Test("pickup cooldown and reappearance",()=>{var w=new World(1,0);var a=w.Add("A");a.Position=new(-18,0,0);a.Health=50;w.Step();Check(a.Health==85);w.Step();Check(a.Health==85);Steps(w,725);Check(a.Health==100);});
        Test("frag limit ends round and restarts",()=>{var w=new World(1,0);var a=w.Add("A");var b=w.Add("B");a.Score=19;b.Invulnerable=0;b.Armor=0;w.Damage(b,200,a);Check(w.Winner=="A");Steps(w,490);Check(w.Winner.Length==0&&a.Score==0);});
        Test("ninety seconds of bot combat remains bounded",()=>{var w=new World();Steps(w,90*60);Check(w.Fighters.Sum(p=>p.Deaths)>0);Check(w.Fighters.All(p=>float.IsFinite(p.Position.X)&&MathF.Abs(p.Position.X)<24&&p.Health>=0&&p.Health<=100&&p.Ammo.All(a=>a>=0)));Console.WriteLine($"  BOT EVIDENCE deaths={w.Fighters.Sum(p=>p.Deaths)}");});
        Test("procedural textures are deterministic and distinct",()=>{var a=Materials.Generate(0);Check(a.SequenceEqual(Materials.Generate(0)));Check(!a.SequenceEqual(Materials.Generate(1)));Check(a.Length==256*256*3);});
        Test("native Windows ABI sizes",()=>{Type T(Type parent,string name)=>parent.GetNestedType(name,BindingFlags.NonPublic)!;Check(Marshal.SizeOf(T(typeof(DesktopWindow),"PixelFormat"))==40);Check(Marshal.SizeOf(T(typeof(DesktopWindow),"WndClass"))==(IntPtr.Size==8?80:48));Check(Marshal.SizeOf(T(typeof(AudioMixer),"Header"))==(IntPtr.Size==8?48:32));Check(Marshal.SizeOf(T(typeof(AudioMixer),"Format"))==18);});
        Test("binary fighter round trip and MTU budget",()=>{var p=new Fighter{Id=19,Name="SIXTEEN-CHAR-TAG",Position=new(1,2,3),Score=9};var w=Wire.Create(Packet.Actors,17);for(int i=0;i<8;i++)Wire.Fighter(w,p);var bytes=Wire.Bytes(w);Check(bytes.Length<=1200);using var r=Wire.Open(bytes,out var type,out ulong token);Check(r!=null&&type==Packet.Actors&&token==17);for(int i=0;i<8;i++){var read=Wire.Fighter(r!);Check(read.Name==p.Name&&read.Position==p.Position&&read.Score==9);}});
        Test("malformed network packets rejected",()=>{Check(Wire.Open(new byte[8],out _,out _)==null);Check(Wire.Open(new byte[1201],out _,out _)==null);Check(!new InputState{Yaw=float.NaN}.Valid);});
        Test("two real UDP clients: join move kill replication disconnect",NetworkMatch);
        Console.WriteLine($"RESULT {passed} passed, {failed} failed");return failed==0?0:1;
    }
    private static void NetworkMatch(){using var host=new MatchHost(0,0,true);host.Start();using var a=new MatchClient($"127.0.0.1:{host.Port}","ALPHA");var b=new MatchClient($"127.0.0.1:{host.Port}","BRAVO");try{var clock=Stopwatch.StartNew();double lastInput=-1;bool kill=false;while(clock.Elapsed.TotalSeconds<18){a.Pump();b.Pump();if(a.Connected&&b.Connected&&a.World.Fighters.Count==2&&clock.Elapsed.TotalSeconds-lastInput>=World.Tick){lastInput=clock.Elapsed.TotalSeconds;var p=a.World.Fighters.Find(p=>p.Id==a.Id);var t=a.World.Fighters.Find(p=>p.Id==b.Id);if(p!=null&&t!=null){var delta=t.Position-p.Position;float dist=MathEx.Horizontal(delta);bool visible=Arena.Visible(p.Position,t.Position);var input=new InputState{Weapon=3,Yaw=MathF.Atan2(delta.X,-delta.Z),Pitch=MathF.Atan2(delta.Y-.45f,dist),Fire=visible};if(!visible){var route=Navigation.Find(p.Position,t.Position);var next=route.FirstOrDefault(n=>MathEx.Horizontal(n-p.Position)>.7f);if(next!=default){var d=next-p.Position;input.Yaw=MathF.Atan2(d.X,-d.Z);input.Pitch=0;input.Forward=1;}}a.Input(input);b.Input(new(){Weapon=0});if(p.Score>=1&&b.World.Fighters.Any(p=>p.Id==a.Id&&p.Score>=1)){kill=true;break;}}}if(host.Error.Length>0)throw new InvalidOperationException(host.Error);Thread.Sleep(2);}
            Check(kill,"Real UDP kill did not replicate within 18 seconds.");Check(a.Received.Any(e=>e.Kind==EventKind.Kill&&e.Owner==a.Id));Check(b.Received.Any(e=>e.Kind==EventKind.Kill&&e.Owner==a.Id));Console.WriteLine($"  UDP EVIDENCE ALPHA score=1; both clients received kill; {clock.Elapsed.TotalSeconds:0.00}s; ping={a.Ping}ms");b.Dispose();for(int i=0;i<100;i++){a.Pump();if(a.World.Fighters.Count==1)break;Thread.Sleep(5);}Check(a.World.Fighters.Count==1,"Disconnect not reflected.");
        }finally{b.Dispose();}}
}
